public static JsonSchemaVersion checkVersion(SpecVersion.VersionFlag versionFlag) {
    if (null == versionFlag)
        return null;

    switch (versionFlag) {
        case V202012 :
            return new Version202012();
        case V201909 :
            return new Version201909();
        case V7 :
            return new Version7();
        case V6 :
            return new Version6();
        case V4 :
            return new Version4();
        default :
            throw new IllegalArgumentException("Unsupported value" + versionFlag);
    }
}

